package fetvisuals.modules.combat;
import fetvisuals.FetVisuals; import fetvisuals.module.*; import fetvisuals.module.settings.*; import fetvisuals.render.RenderUtils; import net.fabricmc.fabric.api.event.player.AttackEntityCallback; import net.minecraft.client.MinecraftClient; import net.minecraft.client.gui.DrawContext; import net.minecraft.util.ActionResult;
public final class ScreenPulse extends fetvisuals.module.Module {private static long pulseUntil;private final NumberSetting duration=add(new NumberSetting("Duration",180,40,600,10));private final ColorSetting color=add(new ColorSetting("Color",0xFFB66DFF));public ScreenPulse(){super("ScreenPulse","Subtle hit screen pulse",Category.COMBAT);AttackEntityCallback.EVENT.register((player,world,hand,entity,hit)->{if(enabled())pulseUntil=System.currentTimeMillis()+(long)duration.get();return ActionResult.PASS;});}public void onHud(DrawContext c,float d){long left=pulseUntil-System.currentTimeMillis();if(left<=0)return;float p=left/(float)duration.get();int a=(int)(70*p);MinecraftClient mc=MinecraftClient.getInstance();int w=mc.getWindow().getScaledWidth(),h=mc.getWindow().getScaledHeight();RenderUtils.rect(c,0,0,w,h,RenderUtils.alpha(color.get(),a));}}
